components.css:
.ds-btn-primary { display: inline-flex; align-items: center; gap: 0.28125rem; cursor: pointer; text-decoration: none; font: 400 1.125rem/1.5 'Atkinson Hyperlegible Next Variable', 'Atkinson Hyperlegible Fallback', system-ui, -apple-system, sans-serif; color: #ffffff; background: #d42274; border: 1px solid #d42274; border-radius: 0.375rem; padding-block: 0.375rem; padding-inline: 0.75rem; }
.ds-btn-primary:hover, .ds-btn-primary:focus-visible { background: #b31d63; border-color: #b31d63; }
.ds-btn-primary:focus-visible { outline: 2px solid #d42274; outline-offset: 2px; }
.ds-btn-primary:disabled { cursor: not-allowed; opacity: 0.6; }

.ds-card { display: block; background: #ffffff; border: 1px solid rgba(33,37,41,0.125); border-radius: 0.375rem; padding: 1.125rem; overflow: hidden; color: inherit; text-decoration: none; }
.ds-card-img { display: block; filter: grayscale(100%); width: calc(100% + 1.125rem * 2); margin-inline: -1.125rem; margin-block-start: -1.125rem; margin-block-end: 0.5625rem; }
.ds-card-title { font: 700 1.125rem/1.4 'Atkinson Hyperlegible Next Variable', 'Atkinson Hyperlegible Fallback', system-ui, -apple-system, sans-serif; margin: 0 0 0.28125rem; color: #212529; }
.ds-card-text { font: 400 1.125rem/1.5 'Atkinson Hyperlegible Next Variable', 'Atkinson Hyperlegible Fallback', system-ui, -apple-system, sans-serif; color: #495057; margin: 0; }

.ds-nav { background: color-mix(in srgb, #ffffff 98%, transparent); padding-block: 0.5625rem; display: flex; align-items: center; gap: 1.125rem; }
.ds-nav-brand { flex-shrink: 0; }
.ds-nav-avatar { width: 42px; height: 42px; border-radius: 50%; display: block; }
.ds-nav-links { display: flex; align-items: center; gap: 1.125rem; }
.ds-nav-link { font: 700 0.875rem/1.4 'Atkinson Hyperlegible Next Variable', 'Atkinson Hyperlegible Fallback', system-ui, -apple-system, sans-serif; color: #212529; text-decoration: none; }
.ds-nav-link:hover { color: #495057; }
.ds-nav-link--active { color: #d42274; text-decoration: underline; }
.ds-nav-link:focus-visible { outline: 2px solid #d42274; outline-offset: 2px; }

.ds-dropdown { display: flex; flex-direction: column; gap: 0.28125rem; min-width: 14rem; padding: 0.5625rem 1.125rem; background: #ffffff; border: 1px solid rgba(33,37,41,0.125); border-radius: 0.375rem; box-shadow: 0 1rem 2rem rgba(33,37,41,0.10); }
.ds-dropdown-link { display: block; font: 700 0.875rem/1.4 'Atkinson Hyperlegible Next Variable', 'Atkinson Hyperlegible Fallback', system-ui, -apple-system, sans-serif; color: #212529; text-decoration: none; }
.ds-dropdown-link:hover { color: #495057; }
.ds-dropdown-divider { width: 100%; height: 1px; margin: 0.28125rem 0; border: none; background: rgba(33,37,41,0.125); }

.ds-entrylist { position: relative; margin: 0; padding-inline-start: 1.125rem; list-style: none; }
.ds-entrylist::before { position: absolute; inset-inline-start: 1.1rem; top: 2rem; bottom: 0; width: 1px; content: ''; background: linear-gradient(to top, rgba(33,37,41,0) 0%, #212529 6.25rem, #212529 100%); }
.ds-entry { position: relative; padding-inline-start: 1.125rem; padding-block-start: 1.125rem; }
.ds-entry::before { position: absolute; top: 2rem; inset-inline-start: 0; width: 0.625rem; height: 0.625rem; content: ''; background-color: #d42274; border-radius: 50%; transform: translateX(-50%); }
.ds-entry-dates { margin: 0 0 0.28125rem; font-size: 0.9375rem; color: #495057; }
.ds-entry-title { font: 700 1.125rem/1.4 'Atkinson Hyperlegible Next Variable', 'Atkinson Hyperlegible Fallback', system-ui, -apple-system, sans-serif; margin: 0; color: #212529; }
.ds-entry-org { font-size: 1.25rem; margin: 0; }
.ds-entry-org-link { color: #d42274; text-decoration: none; }
.ds-entry-body { font: 400 1.125rem/1.5 'Atkinson Hyperlegible Next Variable', 'Atkinson Hyperlegible Fallback', system-ui, -apple-system, sans-serif; color: #212529; margin: 0; }

.ds-field { display: flex; flex-direction: column; gap: 0.28125rem; font-family: 'Atkinson Hyperlegible Next Variable', 'Atkinson Hyperlegible Fallback', system-ui, -apple-system, sans-serif; }
.ds-field-label { display: flex; align-items: center; justify-content: space-between; gap: 0.5625rem; font: 700 0.875rem/1.4 inherit; color: #212529; }
.ds-field-required { color: #495057; border: 1px solid rgba(33,37,41,0.125); border-radius: 9999px; padding-block: 0.125rem; padding-inline: 0.5625rem; font-size: 0.875rem; }
.ds-field-input { font: 400 1.125rem/1.5 inherit; color: #212529; background: #ffffff; border: 1px solid rgba(33,37,41,0.125); border-radius: 0.25rem; padding-block: 0.28125rem; padding-inline: 0.5625rem; }
.ds-field-input--error { border-color: #d42274; box-shadow: 0 0 0 1px #d42274; }
.ds-field-message { display: flex; align-items: center; gap: 0.5625rem; margin: 0; font-size: 0.9375rem; color: #d42274; }
.ds-field-message-icon { display: inline-flex; align-items: center; justify-content: center; width: 1.25rem; height: 1.25rem; border-radius: 9999px; background: #d42274; color: #ffffff; font: 700 0.875rem/1.4 inherit; }

.ds-testimonial { margin: 0; font-family: 'Atkinson Hyperlegible Next Variable', 'Atkinson Hyperlegible Fallback', system-ui, -apple-system, sans-serif; }
.ds-testimonial-quote { margin: 0 0 0.5625rem; padding-inline-start: 1.125rem; font-style: italic; font-size: 1.125rem; color: #495057; }
.ds-testimonial-caption { display: flex; align-items: center; gap: 0.28125rem; font-size: 0.9375rem; color: #495057; }
.ds-testimonial-avatar { width: 40px; height: 40px; border-radius: 50%; }
.ds-testimonial-caption a { color: #d42274; }

.ds-footer { background: #d42274; color: #ffffff; padding-block: 3.375rem; font-family: 'Atkinson Hyperlegible Next Variable', 'Atkinson Hyperlegible Fallback', system-ui, -apple-system, sans-serif; }
.ds-footer, .ds-footer a { color: #ffffff; }
.ds-footer a { text-decoration: none; }
.ds-footer a:hover { text-decoration: underline; }
.ds-footer-inner { display: flex; flex-wrap: wrap; gap: 1.6875rem; margin-bottom: 1.6875rem; }
.ds-footer-section { flex: 1; min-width: 200px; }
.ds-footer-heading { font: 700 1.125rem/1.4 inherit; margin: 0 0 0.5625rem; }
.ds-footer-body { font: 400 1.125rem/1.5 inherit; margin: 0; }
.ds-footer-list { list-style: none; margin: 0; padding: 0; }
.ds-footer-legal { font-size: 0.875rem; opacity: 0.9; margin: 0; }
